export type DemoBlePacket = {
    packetType: 5 | 6;
    packetId: number;
    packetIndex: number;
    delayMs: number;
    sendAtMs: number;
    base64: string;
};

export type DemoBleSession = {
    sessionNo: number;
    packetId: number;
    macAddress: string;
    windowMs: number;
    packetIntervalMs: number;
    totalPackets: number;
    type5PacketCount: number;
    type6PacketCount: number;
    packets: DemoBlePacket[];
};

